        "function": {
            "name": "get_product_details",
            "description": "Get product information including available options (sizes, colors), pricing, and stock status. Can be queried without user authentication.",
            "parameters": {
                "type": "object",
                "properties": {
                    "product_id": {"type": "string", "description": "The product ID to look up"}
                },
                "required": ["product_id"]
            }
        }
    },
    "cancel_pending_order": {
        "type": "function",
        "function": {
            "name": "cancel_pending_order",
            "description": "Cancel a pending order. Requires the order to be in 'pending' status and a valid cancellation reason. The reason must be one of the accepted values. Refund is processed automatically.",
            "parameters": {
                "type": "object",
                "properties": {
                    "order_id": {"type": "string", "description": "The order ID to cancel"},
                    "reason": {"type": "string", "description": "The reason for cancellation"}
