                "type": "object",
                "properties": {
                    "order_id": {"type": "string", "description": "The order ID to modify"},
                    "item_ids": {"type": "array", "items": {"type": "string"}, "description": "List of item IDs to replace"},
                    "new_item_ids": {"type": "array", "items": {"type": "string"}, "description": "List of new item IDs"},
                    "payment_method_id": {"type": "string", "description": "Payment method for any price difference"}
