            "name": "exchange_delivered_order_items",
            "description": "Exchange items in a delivered order for different items of the same product type. A payment method must be provided to handle any price difference between original and new items.",
            "parameters": {
                "type": "object",
                "properties": {
                    "order_id": {"type": "string", "description": "The order ID"},
                    "item_ids": {"type": "array", "items": {"type": "string"}, "description": "List of item IDs to exchange"},
                    "new_item_ids": {"type": "array", "items": {"type": "string"}, "description": "List of new item IDs"},
                    "payment_method_id": {"type": "string", "description": "Payment method for price difference"}
