    "transfer_to_human_agents": {
        "type": "function",
        "function": {
            "name": "transfer_to_human_agents",
            "description": "Transfer the conversation to a human agent. Should only be used when the request cannot be handled within the scope of permitted operations (cancel, modify, return, exchange, information).",
            "parameters": {
                "type": "object",
                "properties": {
                    "summary": {"type": "string", "description": "Summary of the conversation and reason for transfer"}
                },
