def load_generated_data():
    """Run the three generator scripts and merge their output."""
    data = {}
    for script in ["_gen_scopal.py", "_gen_lexical.py", "_gen_incompleteness.py"]:
        result = subprocess.run(
            [sys.executable, script],
            capture_output=True, text=True, check=True,
        )
        data.update(json.loads(result.stdout))
    return data


def main():
    with open("clause_templates.json") as f:
        clauses = json.load(f)

    generated = load_generated_data()

    missing = []
    for clause in clauses:
        cid = clause["clause_id"]
        if cid not in generated:
            missing.append(cid)
            continue

        gdata = generated[cid]

        # Rename fields
        if "ambiguous_version" in clause:
            clause["ambiguous_clause"] = clause.pop("ambiguous_version")
        if "unambiguous_version" in clause:
            clause["unambiguous_clause"] = clause.pop("unambiguous_version")

        # Add new fields
        clause["user_scenario"] = gdata["user_scenario"]

        tool_names = gdata["tool_names"]
        clause["tools"] = [TOOLS_FULL[n] for n in tool_names if n in TOOLS_FULL]
        clause["stripped_tool_desc"] = [TOOLS_STRIPPED[n] for n in tool_names if n in TOOLS_STRIPPED]
        clause["tool_responses"] = gdata["tool_responses"]

    if missing:
        print(f"WARNING: {len(missing)} clauses missing from generated data: {missing}", file=sys.stderr)

    with open("clause_templates.json", "w") as f:
        json.dump(clauses, f, indent=2, ensure_ascii=False)

    print(f"Updated {len(clauses)} clauses in clause_templates.json")
    print(f"  - All have user_scenario: {all('user_scenario' in c for c in clauses)}")
    print(f"  - All have tools: {all('tools' in c for c in clauses)}")
    print(f"  - All have tool_responses: {all('tool_responses' in c for c in clauses)}")
    print(f"  - All have ambiguous_clause: {all('ambiguous_clause' in c for c in clauses)}")


if __name__ == "__main__":
    main()

